    '<div class="concepts">' + step('Modelo', 'Raciocina e produz propostas.') + step('Skill', 'Descreve um método de trabalho.') + step('Harness', 'Controla execução, estado e verificações.', 'orange') + step('Interface', 'Ajuda a pessoa a acompanhar e decidir.') + '</div><p class="takeaway">O Software Factory conecta essas peças em um processo de desenvolvimento.</p>',
