# Revision requested by the developer team: explain the workflow before the methods.
revisions = {
    'grilling': ('Grilling', 'Grilling: decisões em rodadas com dependências'),
    'arvore': ('Dependências entre perguntas', 'Como uma resposta libera a próxima rodada'),
    'ui-grill': ('Perguntas na interface', 'Protótipo: perguntas, respostas e discussão'),
    'ui-plano': ('Revisão e aprovação', 'Revisão do plano e aprovação das versões'),
    'wayfinder': ('Mapa Wayfinder', 'Wayfinder: mapa de decisões e dependências'),
    'wayfinder-tipos': ('Tipos de ticket', 'Tipos de ticket e como são resolvidos'),
    'metodos': ('Fluxos de planejamento', 'Fluxos de planejamento: Grill e Wayfinder'),
    'harness': ('Arquitetura', 'Controlador, interfaces e workers'),
    'workflow': ('Execução e correção', 'Workflow de execução e ciclos de correção'),
    'evidencia': ('Estado e validação', 'Persistência, recuperação e validação'),
    'ponte': ('Integração pendente', 'Integração pendente: planejamento e execução'),
    'estado': ('Estado atual', 'Estado atual da implementação'),
    'evolucao': ('Frentes de trabalho', 'Frentes de trabalho para o time'),
    'convite': ('Como participar', 'Próximas contribuições ao Software Factory'),
    'fontes': ('Referências', 'Referências e evidências'),
}
for slide in slides:
    if slide['id'] in revisions:
        slide['label'], slide['title'] = revisions[slide['id']]
    slide['body'] = slide['body'].replace('A pessoa pode inspecionar o que foi decidido, executado e verificado.', 'Por execução: decisões, logs de verificação e versão dos arquivos.')
    slide['body'] = slide['body'].replace('<h3>O motor</h3>', '<h3>Controlador</h3>').replace('<h3>A experiência</h3>', '<h3>Interface de planejamento</h3>').replace('<h3>A conexão</h3>', '<h3>Integrações pendentes</h3>')
    slide['body'] = slide['body'].replace('Caminho claro', 'Decisões resolvidas').replace('Preparar o próximo trabalho.', 'Consolidar a especificação.')
    slide['body'] = slide['body'].replace('Traga um caso real.<br>Teste o fluxo.<br>Ajude a construir a próxima peça.', 'Escolha um fluxo para testar.<br>Registre o que falhou.<br>Proponha a próxima mudança.')
    slide['body'] = slide['body'].replace('Qual parte você gostaria de ajudar a evoluir?', 'Discussão com o time: qual integração devemos priorizar?')
    slide['notes'] = slide['notes'].replace('Esta é a principal oportunidade do projeto.', 'Este é o trabalho de integração pendente.')
    slide['notes'] = slide['notes'].replace('Use esta lâmina para não confundir a maturidade das partes.', 'Apresente separadamente o estado de implementação e a evidência de teste de cada parte.')
    slide['notes'] = slide['notes'].replace('Convide pessoas de diferentes perfis.', 'Discuta a divisão de trabalho entre desenvolvimento, produto e qualidade.')
    if slide['id'] == 'quatro-pecas':
        slide['label'] = 'Visão do workflow'
        slide['title'] = 'Workflow: do pedido à execução'
        slide['body'] = (
            '<div class="workflow-overview"><div class="overview-lane"><span class="path-label">Planejamento · Grill em protótipo; Wayfinder proposto</span>'
            + row([step('Pedido', 'Definir a mudança e o contexto do repositório.'), step('Grill / Wayfinder', 'Resolver decisões e registrar dependências.'), step('Plano aprovado', 'Revisar escopo, critérios e documentos.')])
            + '</div><div class="overview-handoff"><strong>Integração pendente</strong><span>Entregar a versão aprovada ao controlador.</span></div>'
            + '<div class="overview-lane"><span class="path-label">Execução · implementada no harness</span>'
            + row([step('Baseline + Planner', 'Verificar o estado inicial e detalhar o plano técnico.'), step('Builder + Testes', 'Alterar o código, executar checks e corrigir falhas.'), step('Review + Finalize', 'Revisar a mudança e conferir a versão testada.', 'orange')])
            + '</div><p class="caption">Saída: <code>ready_for_review</code>. Testes e revisões podem retornar ao Builder, com limites de tentativas.</p></div>'
        )
        slide['notes'] = ('Comece pelo fluxo de desenvolvimento. No planejamento, um pedido delimitado passa pelo Grill; um esforço maior pode usar Wayfinder para organizar decisões em tickets. O time revisa escopo, critérios e documentos antes de aprovar a versão. No protótipo, esse caminho é simulado. A integração do plano aprovado ao controlador ainda precisa ser implementada. O harness existente executa bootstrap, baseline, Planner, Builder, testes, revisão e finalização. Falhas de teste geram reparo e novo teste; bloqueios de revisão geram revisão da implementação, teste e nova revisão. A saída é ready_for_review. Este quadro antecipa o fluxo; as próximas telas detalham os métodos e depois o grafo de execução. Não confundir o planejamento técnico interno do Planner com o Grill anterior à aprovação.')
    if slide['id'] == 'convite':
        slide['notes'] = ('Feche com a discussão de trabalho do time. Escolher um caso pequeno, rodar o protótipo, registrar problemas e propor uma mudança são formas de começar. Para implementação, a próxima integração é salvar as rodadas e versões de planejamento no controlador e iniciar o run a partir do plano aprovado. Use a issue 10 para organizar a discussão. Mantenha o convite à participação vinculado a uma contribuição concreta.')

