JS = '''
const chapters=[...document.querySelectorAll('.chapter')],links=[...document.querySelectorAll('.chapter-nav a')],pages=[document.querySelector('.cover'),...chapters];
function update(){let active=chapters[0];for(const c of chapters){if(c.getBoundingClientRect().top<=innerHeight*.25)active=c;}if(innerHeight+scrollY>=document.documentElement.scrollHeight-4)active=chapters.at(-1);for(const a of links){const selected=a.hash==='#'+active.id;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');}}
addEventListener('scroll',update,{passive:true});addEventListener('resize',update);update();
document.querySelector('#notes').onclick=()=>{document.body.classList.toggle('notes-on');document.querySelector('#notes').setAttribute('aria-pressed',String(document.body.classList.contains('notes-on')));};
function togglePresent(){const current=pages.reduce((best,p)=>Math.abs(p.getBoundingClientRect().top)<Math.abs(best.getBoundingClientRect().top)?p:best,pages[0]);document.body.classList.toggle('presenting');current.scrollIntoView({behavior:'instant'});update();}
document.querySelector('#present').onclick=togglePresent;document.querySelector('#exit-present').onclick=togglePresent;
function move(delta){let ix=pages.findIndex(p=>p.getBoundingClientRect().bottom>innerHeight*.5);if(ix<0)ix=pages.length-1;pages[Math.max(0,Math.min(pages.length-1,ix+delta))].scrollIntoView({behavior:'smooth'});}
document.querySelector('#previous').onclick=()=>move(-1);document.querySelector('#next').onclick=()=>move(1);
addEventListener('keydown',e=>{if(e.target.closest('button,input,textarea,select')||document.querySelector('dialog[open]'))return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();move(-1);}if(e.key==='Escape'&&document.body.classList.contains('presenting'))togglePresent();});
const lightbox=document.querySelector('.lightbox');document.querySelectorAll('.screenshot-button').forEach(b=>b.onclick=()=>{lightbox.querySelector('img').src=b.querySelector('img').src;lightbox.showModal();});lightbox.querySelector('button').onclick=()=>lightbox.close();lightbox.onclick=e=>{if(e.target===lightbox)lightbox.close();};
'''

